@startuml

class Department {}

class Room {}

class Bed {
  + Category : StayCategory
}

class StayCategory {
  + Price : double
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
}

class Stay {
  + StartDate : date
  + Status : string
}

class Registration {
  + RegistrationDate : date
  + BasicData : string
}

class Assessment {
  + Needs : string
  + ResultingStayType : StayType
}

class WaitingListPosition {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + Amount : double
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" StayCategory
Inhabitant "1" -- "*" Stay
Stay "0..*" -- "1" StayCategory
Inhabitant "1" -- "0..*" Registration
Registration "1" -- "0..1" Assessment
Inhabitant "1" -- "0..*" WaitingListPosition
StayType "1" -- "0..*" WaitingListPosition
WaitingListPosition "1" -- "0..1" Proposal
Inhabitant "1" -- "0..*" Proposal
Inhabitant "1" -- "0..*" Invoice
Stay "1" -- "0..*" Invoice
Invoice "0..*" -- "0..1" CreditNote

@enduml

